let timer;document.querySelectorAll('[data-copy]').forEach(button=>button.addEventListener('click',async()=>{const url=new URL(location.href);url.hash=button.dataset.copy;try{await navigator.clipboard.writeText(url.href);document.getElementById('notice').textContent='Public '+(button.dataset.copy?'option':'comparison')+' link copied.';}catch{document.getElementById('notice').textContent='Copy the page address from your browser to share this design.';}clearTimeout(timer);timer=setTimeout(()=>document.getElementById('notice').textContent='',4000);}));
